from __future__ import annotations

import socket
import urllib.request

from secretscan.model import InternetCheck, InternetStatus, Module, ModuleStatus

_CHECKS = [
    ("DNS (Cloudflare)", "1.1.1.1", 53, "dns"),
    ("HTTP", "example.com", 80, "http"),
    ("HTTPS", "example.com", 443, "https"),
    ("SSH (GitHub)", "github.com", 22, "ssh"),
    ("FTP (GNU)", "ftp.gnu.org", 21, "ftp"),
    ("SMTP (port 25)", "smtp.gmail.com", 25, "smtp"),
    ("SMTP (port 587)", "smtp.gmail.com", 587, "smtp-submission"),
    ("IMAPS (Gmail)", "imap.gmail.com", 993, "imaps"),
    ("POP3S (Gmail)", "pop.gmail.com", 995, "pop3s"),
]


def check_internet() -> tuple[InternetStatus, ModuleStatus]:
    status = ModuleStatus(module=Module.INTERNET)
    result = InternetStatus()

    for name, host, port, protocol in _CHECKS:
        status.attempted += 1
        check = InternetCheck(name=name, host=host, port=port, protocol=protocol)
        try:
            sock = socket.create_connection((host, port), timeout=5)
            sock.close()
            check.reachable = True
        except Exception as e:
            check.error = str(e)
        result.checks.append(check)
        status.accessed += 1

    try:
        req = urllib.request.Request("https://api.ipify.org", method="GET")
        with urllib.request.urlopen(req, timeout=5) as resp:
            result.public_ip = resp.read().decode().strip()
    except Exception:
        pass

    status.note = (
        "tests outbound connectivity only; makes real outbound calls "
        "(an IP-echo service, TCP connects to public endpoints)"
    )
    return result, status
